export function cabinetView(ctx){const ui=overlay('radial-gradient(circle at 50% 20%,#4a3626,#150e09)');ui.c.style.display='none';const R=restored();const got=LJ('muui-h3-sets',[]);
 title(ui.top,'내 진열장',`복원한 유물 ${R.size} / ${ART.length} · 완성한 세트 ${SETS.filter(s=>s.k.every(k=>R.has(k))).length} / ${SETS.length}`);
 const box=document.createElement('div');box.style.cssText='position:absolute;left:50%;top:110px;bottom:12px;transform:translateX(-50%);width:min(900px,96vw);overflow-y:auto;-webkit-overflow-scrolling:touch;z-index:2;padding:0 4px';requestAnimationFrame(()=>{try{box.style.top=Math.round(ui.top.getBoundingClientRect().bottom+10)+'px'}catch(e){}});
 const PC=['#6a5a48','#b0703a','#c8ccd4','#e8b840'],PN=['','구리','은','금'];
 box.innerHTML=SETS.map(S=>{const full=S.k.every(k=>R.has(k));return `<section style="margin:0 0 18px"><div style="display:flex;align-items:baseline;gap:8px;margin:0 6px 4px"><b style="font:20px 'Do Hyeon',sans-serif;color:#f2d27a">${S.n}</b><span style="font:13px 'Gowun Dodum',sans-serif;color:${full?'#ffd27a':'#c8b8a0'}">${full?'✦ 세트 완성':S.k.filter(k=>R.has(k)).length+' / '+S.k.length}</span></div><div style="display:flex;justify-content:space-around;align-items:flex-end;gap:6px;padding:14px 10px 0;min-height:176px;background:linear-gradient(180deg,rgba(90,66,46,.55),rgba(40,28,20,.75));border-radius:10px 10px 0 0;box-shadow:inset 0 10px 24px rgba(0,0,0,.45)">`+S.k.map(k=>{const a=ART.find(x=>x.k===k);if(!a)return'';const dn=R.has(k),st=dn?Math.max(1,starOfArt(k)):0;return `<button type="button" ${dn?`data-k="${k}"`:'disabled'} style="flex:1;max-width:190px;min-width:0;background:none;border:0;padding:0;cursor:${dn?'pointer':'default'};color:#f3ead6;text-align:center"><div style="height:124px;display:flex;align-items:flex-end;justify-content:center">${dn?`<img src="${THUMB(k)}" alt="${a.n}" style="max-height:124px;max-width:100%;object-fit:contain;filter:drop-shadow(0 8px 8px rgba(0,0,0,.55))">`:`<span style="font:46px 'Do Hyeon',sans-serif;color:rgba(243,234,214,.18);padding-bottom:22px">?</span>`}</div><div style="height:14px;margin:0 auto;width:78%;border-radius:4px 4px 0 0;background:linear-gradient(180deg,${PC[st]},rgba(0,0,0,.35));box-shadow:0 -1px 0 rgba(255,255,255,.25) inset"></div><div style="font:14px 'Do Hyeon',sans-serif;padding:5px 2px 2px;color:${dn?'#f2d27a':'#8a7a66'};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${dn?a.n:'복원 전'}</div><div style="font:12px 'Gowun Dodum',sans-serif;color:${dn?'#f2c14e':'#6a5a48'};letter-spacing:1px;height:16px">${dn?'★'.repeat(st)+'☆'.repeat(3-st):a.n}</div></button>`}).join('')+`</div><div style="height:16px;background:linear-gradient(180deg,#7a5634,#4a3220);border-radius:0 0 6px 6px;box-shadow:0 6px 12px rgba(0,0,0,.5)"></div></section>`}).join('')+`<div style="text-align:center;margin:4px 0 16px"><button type="button" data-shop="1" style="font:17px 'Do Hyeon',sans-serif;padding:10px 20px;border-radius:12px;border:0;background:#8e2b20;color:#fff4dc;cursor:pointer">복원하러 가기</button></div><div style="text-align:center;color:rgba(243,234,214,.65);font:12px 'Gowun Dodum',sans-serif;padding-bottom:10px">받침 색은 복원 솜씨예요. 별 하나 구리, 둘 은, 셋 금. 유물을 누르면 크게 돌려 볼 수 있어요.</div>`;
 ui.o.append(box);box.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.shop){ui.o.remove();workshopGame(ctx);return}if(b.dataset.k){ui.o.remove();artViewer(b.dataset.k,{again:k=>restoreGame(ctx,k),onClose:()=>cabinetView(ctx)})}});ui.x.onclick=()=>ui.o.remove();window.__CABV={close:()=>ui.o.remove()}}
